// French texts of catalog.mjs: [English text, French text], in catalog order. The English side must match the T()
// text exactly (the build names any text without a translation and any entry whose English text changed or went
// away). Terms follow the app (src/Filee.App/Assets/i18n/fr.json): préréglage (preset), moteur / moteurs facultatifs
// (engines), menu circulaire (donut), tranche (slice), dossiers surveillés (watch folders), zone de dépôt (drop zone),
// livre numérique (e-book), preset names as in the app (Compresser le PDF, Fusionner les PDF, Vectoriser en SVG…).
// French typography as in the app: a no-break space before : ; ? ! and %, and inside « ».

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `la vidéo et l'audio, l'extraction des sous-titres et l'enregistrement en HEIC`],
  [`older office formats such as DOC, PPT and ODT`,
    `les anciens formats bureautiques comme DOC, PPT et ODT`],
  [`rare e-book formats and MOBI/AZW3 output`,
    `les formats de livres numériques rares et la sortie MOBI/AZW3`],
  [`EPS and PostScript`,
    `EPS et PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc et d'autres langages de balisage, Word → Markdown et Markdown → diapositives`],

  // Options
  [`quality`, `qualité`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Qualité réglable pour JPG, WEBP et AVIF : le JPG est enregistré à 90 % par défaut, et le préréglage JPG 70% produit des fichiers plus légers.`],
  [`resize`, `redimensionner`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Redimensionnez pendant la conversion, en pourcentage (par exemple de moitié) ou en limitant le grand côté.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Définissez le DPI inscrit dans l'image, par exemple 300 pour l'impression.`],
  [`grayscale`, `niveaux de gris`],
  [`A grayscale preset makes black-and-white copies.`,
    `Le préréglage Niveaux de gris produit des copies en noir et blanc.`],
  [`metadata`, `métadonnées`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `Les métadonnées (EXIF, XMP, profil de couleur) sont conservées par défaut et peuvent être supprimées pour préserver la confidentialité.`],
  [`ICO sizes`, `tailles d'ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Les fichiers ICO contiennent par défaut 256, 128, 64, 48, 32 et 16 px ; les tailles se modifient dans le préréglage.`],
  [`TIFF compression`, `compression TIFF`],
  [`TIFF compression can be chosen (LZW by default).`,
    `La compression TIFF peut être choisie (LZW par défaut).`],
  [`white background`, `fond blanc`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `Le JPG ne gère pas la transparence : les zones transparentes sont remplies de blanc.`],
  [`merge into one PDF`, `fusionner en un seul PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Le préréglage Fusionner les PDF réunit tous les fichiers déposés en un seul PDF.`],
  [`split pages`, `diviser les pages`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Le préréglage Diviser le PDF enregistre chaque page dans son propre PDF, dans un sous-dossier.`],
  [`rotate & flip`, `pivoter et retourner`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `Les préréglages Rotation et Retourner font pivoter les images à gauche, à droite ou de 180° et les retournent en miroir, après application de l'orientation propre à la photo.`],
  [`Trace to SVG`, `Vectoriser en SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Deux préréglages vectorisent une image en formes vectorielles : Vectoriser en SVG, jusqu'à 64 couleurs, et Trait en SVG, en noir, pour les logos, signatures et numérisations. Aucun autre programme n'est nécessaire.`],
  [`remove background`, `détourer`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Le préréglage Détourer rend transparent un arrière-plan uni : le papier derrière une signature ou un tampon, le fond d'un logo.`],
  [`page ranges`, `plages de pages`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Des plages de pages comme 1-3,5 limitent la conversion aux pages dont vous avez besoin.`],
  [`render DPI`, `DPI de rendu`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Les pages sont rendues à 150 DPI par défaut ; choisissez 300 DPI pour une qualité d'impression.`],
  [`one long image`, `une image longue`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Le préréglage Image longue empile toutes les pages dans une seule image haute, par exemple pour publier tout un document d'un coup.`],
  [`compress PDF`, `compresser le PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `Le préréglage Compresser le PDF allège un PDF qui reste un PDF : les images sont réduites à 72, 150 ou 300 ppp et les photos réenregistrées en JPEG, tandis que le texte, les polices, les liens, les signets et les formulaires restent intacts. Un PDF impossible à alléger est laissé tel quel. Si Ghostscript est installé, Filee peut aussi l'essayer et garder le résultat le plus léger.`],
  [`a picture per slide`, `une image par diapositive`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (diapos) place une image de chaque page sur sa propre diapositive, à la taille de la page, avec le texte de la page dans les notes du présentateur. Les diapositives sont fidèles au PDF mais ne sont pas modifiables ; convertissez en DOCX pour obtenir du texte modifiable.`],
  [`vector PDF`, `PDF vectoriel`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `Le PDF reste vectoriel : il est net à tous les niveaux de zoom et à l'impression.`],
  [`editable`, `modifiable`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Le résultat contient du vrai texte et des paragraphes modifiables, pas des images de pages.`],
  [`attachments as ZIP`, `pièces jointes en ZIP`],
  [`Attachments can be saved separately as one ZIP.`,
    `Les pièces jointes peuvent être enregistrées à part, dans un seul ZIP.`],
  [`one CSV per sheet`, `un CSV par feuille`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Les classeurs à plusieurs feuilles donnent un CSV par feuille.`],
  [`layout kept`, `mise en page conservée`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Conserve le format de page et les marges, les en-têtes et pieds de page avec numéros de page, les tableaux, les zones de texte, les formes et les images.`],
  [`no Office needed`, `sans Office`],
  [`No Microsoft Office or LibreOffice needed.`,
    `Ni Microsoft Office ni LibreOffice ne sont nécessaires.`],
  [`no Hancom Office needed`, `sans Hancom Office`],
  [`No Hancom Office and no approval dialog.`,
    `Sans Hancom Office et sans fenêtre d'autorisation.`],
  [`no AutoCAD needed`, `sans AutoCAD`],
  [`No AutoCAD or DWG viewer needed.`,
    `Ni AutoCAD ni visionneuse DWG ne sont nécessaires.`],
  [`no re-encoding`, `sans réencodage`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Quand le nouveau format peut contenir la vidéo et le son tels quels (un MOV d'iPhone → MP4), ils changent seulement de conteneur : aucune perte de qualité, HDR conservé, terminé en quelques secondes.`],
  [`720p option`, `option 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `Le préréglage MP4 720p réduit les grandes vidéos pour les partager.`],
  [`extract audio`, `extraire le son`],
  [`Only the sound is saved, without the video track.`,
    `Seul le son est enregistré, sans la piste vidéo.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `Le préréglage MP3 128k produit des fichiers plus légers, idéal pour la voix.`],
  [`extract`, `extraire`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Le préréglage Extraire, lui, décompresse une archive dans un dossier.`],
  [`pack into one ZIP`, `réunir dans un seul ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `N'importe quelle sélection de fichiers peut être réunie dans un seul ZIP.`],
  [`DRM-free books`, `livres sans DRM`],
  [`Works with DRM-free books only.`,
    `Fonctionne uniquement avec des livres sans DRM.`],
  [`ALAC in M4A`, `ALAC en M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`,
    `Le M4A peut contenir de l'ALAC sans perte aussi bien que de l'AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `Les préréglages vidéo peuvent encoder en HEVC (H.265) ou en AV1 pour des fichiers plus légers, en conservant la vidéo 10 bits et HDR.`],
  [`hardware encoding`, `accélération matérielle`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Activez Utiliser l'accélération matérielle dans un préréglage vidéo pour encoder le H.264 et le HEVC sur la puce graphique (NVENC, Quick Sync, AMF, VideoToolbox ou VA-API) : beaucoup plus rapide et moins gourmand en énergie, un peu plus lourd à qualité égale. Cette option est désactivée par défaut et, sans puce compatible, la vidéo est encodée comme avant.`],
  [`every frame`, `chaque image`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Une vidéo donne normalement une seule image fixe. Les préréglages Extraire les images, ou l'option Enregistrer chaque image d'une vidéo d'un préréglage PNG ou JPG, enregistrent chaque image (ou une sur N) dans un dossier à côté de la vidéo.`],
  [`extract subtitles`, `extraire les sous-titres`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Le préréglage Extraire les sous-titres, dans le menu circulaire des vidéos, enregistre en SRT la première piste de sous-titres texte d'une vidéo.`],
  [`saved as UTF-8`, `enregistré en UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `Les résultats sont enregistrés en UTF-8. Les fichiers coréens enregistrés en CP949 (EUC-KR) sont détectés et lus correctement.`],
  [`tables to CSV / Excel`, `tableaux vers CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `Les données qui forment un tableau (une liste d'enregistrements) se convertissent aussi depuis et vers CSV et Excel.`],
  [`picture preview`, `aperçu en image`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG ou JPG donne une image ombrée du modèle, vu de face, de droite et d'en haut.`],
  [`colours and textures`, `couleurs et textures`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Les couleurs, textures et matériaux sont conservés quand le format cible peut les contenir. Le STL ne garde que la forme.`],
  [`HDR tone-mapped`, `HDR par tone mapping`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Les captures d'écran HDR que Windows enregistre en JPEG XR sont ramenées à une luminosité normale par tone mapping, au lieu d'être écrêtées.`],
  [`Live Photo video`, `vidéo de la Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Le préréglage Vidéo Live enregistre en MP4 ou MOV la vidéo d'une Live Photo d'iPhone (un LIVP d'iCloud, ou une photo avec son MOV) ou d'une Motion Photo Android. Dans l'autre sens, les préréglages Live Photo (iPhone) et Motion Photo (Android) transforment un court extrait d'une vidéo en photo animée ; c'est encore expérimental.`],
  [`WGS 84 longitude / latitude`, `longitude / latitude WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `Les résultats sont toujours en longitude et latitude (WGS 84). Les Shapefiles en UTM, Web Mercator, Lambert ou Albers sont convertis et s'ouvrent donc au bon endroit ; convertir un fichier dans son propre format le reprojette.`],
  [`save as ZIP`, `enregistrer en ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Un Shapefile se compose de cinq fichiers (.shp, .shx, .dbf, .prj et .cpg). Avec Enregistrer le résultat en ZIP dans un préréglage, ou pour tous les résultats géospatiaux dans les paramètres, ils voyagent ensemble dans un seul ZIP.`],
  [`Canon CR2 RAW photo`, `Photo RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `Le CR2 est le format de photo RAW utilisé pendant de nombreuses années par les reflex Canon (les modèles Canon récents écrivent du CR3). Il stocke les données brutes du capteur, ce qui laisse beaucoup de latitude pour la retouche.`],
  [`Nikon NEF RAW photo`, `Photo RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `Le NEF est le format de photo RAW de Nikon, utilisé par les reflex Nikon et les hybrides de la série Z. Comme les autres fichiers RAW, il contient les données brutes du capteur et pèse plusieurs fois plus lourd qu'un JPG.`],

  // Images
  [`Images`, `Images`],
  [`images`, `images`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Photos et graphiques, dont les HEIC et Live Photos d'iPhone, les PSD de Photoshop, les RAW d'appareil photo de toutes les grandes marques, les APNG animés, le DICOM et les captures d'écran HDR de Windows (JPEG XR). Redimensionnez, faites pivoter, réglez la qualité et le DPI ou supprimez les métadonnées pendant la conversion, ou vectorisez une image en SVG.`],
  [`JPEG image`, `Image JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `Le JPEG est le format photo le plus répandu. Sa compression avec perte garde les fichiers légers, mais chaque enregistrement à qualité réduite efface des détails, et il ne gère pas la transparence.`],
  [`PNG image`, `Image PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `Le PNG est un format d'image sans perte avec transparence, idéal pour les captures d'écran, les logos et les graphiques aux contours nets. Une photo enregistrée en PNG est généralement bien plus lourde qu'en JPG.`],
  [`WebP image`, `Image WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `Le WebP est le format d'image de Google pour le web. Il gère la compression avec ou sans perte et la transparence, et il est généralement plus léger que le JPG ou le PNG, mais certains éditeurs et formulaires d'envoi ne l'acceptent toujours pas.`],
  [`AVIF image`, `Image AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `L'AVIF est un format d'image moderne basé sur le codec vidéo AV1. Il compresse mieux que le JPG et le WebP, mais sa prise en charge par les logiciels et appareils anciens reste limitée.`],
  [`HEIC / HEIF image`, `Image HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `Le HEIC (HEIF) est le format photo utilisé par défaut sur iPhone et iPad. Les photos pèsent souvent environ deux fois moins qu'en JPG, mais beaucoup d'applications Windows, de sites web et d'appareils anciens ne savent pas les ouvrir.`],
  [`GIF image / animation`, `Image / animation GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `Le GIF est un ancien format d'image limité à 256 couleurs qui gère les animations simples. Il reste le moyen universel de partager de courtes boucles muettes dans les discussions, les documents et les rapports de bug.`],
  [`Windows icon`, `Icône Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `L'ICO est le format d'icône de Windows. Un seul fichier ICO contient la même image en plusieurs tailles (par exemple 16, 32, 48 et 256 pixels) pour rester net partout, de la barre des tâches aux favicons des sites web.`],
  [`Photoshop document`, `Document Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `Le PSD est le format natif d'Adobe Photoshop. Il conserve les calques, les masques et les réglages, ce qui en fait un excellent format de travail, mais la plupart des visionneuses et des sites web ne savent pas l'ouvrir.`],
  [`macOS icon`, `Icône macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `L'ICNS est le format d'icône de macOS. Comme l'ICO, il regroupe plusieurs tailles d'une même image, jusqu'à 1024×1024 pour les écrans Retina, et sert aux icônes d'applications sur Mac.`],
  [`Camera RAW`, `RAW d'appareil photo`],
  [`Windows only`, `Windows uniquement`],
  [`the photo of the Live Photo`, `la photo de la Live Photo`],
  [`the video of the Live Photo`, `la vidéo de la Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Graphiques vectoriels`],
  [`vector graphics`, `graphiques vectoriels`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, métafichiers Windows, Illustrator, EPS/PostScript et dessins CorelDRAW, Visio et LibreOffice Draw. Le SVG devient aussi DXF ou DWG pour la CAO.`],
  [`SVG vector graphic`, `Graphique vectoriel SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `Le SVG est un format de graphiques vectoriels basé sur XML. Les formes et le texte restent nets à toutes les tailles, ce qui le rend idéal pour les logos et les icônes sur le web, mais beaucoup d'applications et de formulaires d'envoi n'acceptent que des images matricielles.`],
  [`Encapsulated PostScript`, `PostScript encapsulé`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `L'EPS est un format vectoriel issu de l'impression et du graphisme, souvent utilisé pour les logos et illustrations envoyés aux imprimeurs. La plupart des applications modernes ne peuvent pas l'afficher sans interpréteur PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`,
    `fichiers AI enregistrés avec contenu PDF (le réglage par défaut d'Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Transformez des PDF en images, en documents Word ou HWPX modifiables, en diapositives PowerPoint, en texte ou en archive de bande dessinée, et fusionnez, divisez, compressez ou sélectionnez des pages.`],
  [`PDF document`, `Document PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `Le PDF est la norme pour partager des documents qui doivent s'afficher de la même façon partout. Polices, mise en page et images sont figées, et il s'ouvre sur tous les appareils. C'est aussi ce qui rend les PDF difficiles à modifier.`],
  [`one page`, `une page`],

  // Documents
  [`Documents`, `Documents`],
  [`documents`, `documents`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Documents Word sans Microsoft Office, factures électroniques chinoises OFD, formats de traitement de texte anciens et rares avec le moteur facultatif LibreOffice, et e-mails enregistrés (EML et MSG Outlook).`],
  [`Word document`, `Document Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `Le DOCX est le format de Microsoft Word depuis Word 2007 (Office Open XML). C'est le format le plus courant pour les documents modifiables : rapports, lettres, formulaires.`],
  [`Word 97–2003 document`, `Document Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `Le DOC est le format binaire de Word 97–2003. Les anciennes archives, les formulaires officiels et les systèmes hérités en produisent encore, mais il est remplacé peu à peu par le DOCX.`],
  [`E-mail message`, `Message e-mail`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `L'EML est un e-mail enregistré dans un fichier (format MIME), avec les en-têtes, le message et ses pièces jointes. La plupart des logiciels de messagerie, dont Outlook et Thunderbird, savent l'ouvrir.`],
  [`Outlook message`, `Message Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `Le MSG est le fichier que Microsoft Outlook enregistre quand vous faites glisser un e-mail hors de sa fenêtre. Seul Outlook l'ouvre : il est donc difficile à lire sur un PC sans Outlook ou sur un téléphone.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX coréens`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Documents coréens Hancom Hangul sans Hancom Office : HWP ↔ HWPX, vers PDF, images, Word, texte, Markdown et HTML, et HWPX à partir de Word, Excel, PowerPoint, Markdown et PDF.`],
  [`Hangul document (HWP)`, `Document Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `Le HWP est le format de document de Hancom Office Hangul (한글), le traitement de texte de référence dans les administrations, les écoles et de nombreuses entreprises coréennes. Hors de Corée, peu de programmes savent l'ouvrir.`],
  [`Hangul document (HWPX)`, `Document Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `Le HWPX est le format ouvert, basé sur XML, de Hancom Hangul (OWPML, norme nationale coréenne KS X 6101). Les institutions publiques coréennes l'adoptent à la place du format binaire HWP.`],

  // Spreadsheets
  [`Spreadsheets`, `Feuilles de calcul`],
  [`spreadsheets`, `feuilles de calcul`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Feuilles Excel, OpenDocument et CSV/TSV, en PDF avec un ajustement à la page comme dans Excel ou entre elles, sans Excel.`],
  [`Excel workbook`, `Classeur Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `Le XLSX est le format de classeur de Microsoft Excel depuis Excel 2007. Un classeur peut contenir plusieurs feuilles avec formules, mise en forme, graphiques et images.`],
  [`Excel 97–2003 workbook`, `Classeur Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `Le XLS est le format binaire de classeur d'Excel 97–2003. Beaucoup de systèmes anciens et d'exports bancaires ou comptables en produisent encore.`],
  [`Comma-separated values`, `Valeurs séparées par des virgules`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `Le CSV est du texte brut avec une ligne de tableau par ligne. Tous les tableurs, bases de données et langages de programmation le lisent, mais il n'a ni mise en forme, ni formules, ni feuilles multiples.`],

  // Presentations
  [`Presentations`, `Présentations`],
  [`presentations`, `présentations`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint en PDF, en images et en HWPX sans PowerPoint ; anciens PPT, ODP et Keynote avec le moteur facultatif LibreOffice.`],
  [`PowerPoint presentation`, `Présentation PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `Le PPTX est le format de Microsoft PowerPoint depuis PowerPoint 2007. Il contient des diapositives avec texte, images, formes, tableaux, notes et animations.`],
  [`PowerPoint 97–2003 presentation`, `Présentation PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `Le PPT est le format binaire de PowerPoint 97–2003. Les anciens supports de cours et les présentations archivées sont souvent encore en PPT.`],

  // Text & markup
  [`Text & markup`, `Texte et balisage`],
  [`text and markup`, `texte et balisage`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Texte brut, Markdown, HTML et pages web enregistrées (MHTML) en PDF, Word, HWPX et EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter et les autres langages de balisage passent par le moteur facultatif Pandoc, qui transforme aussi le Markdown en diapositives PowerPoint.`],
  [`Plain text`, `Texte brut`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `Le TXT est du texte brut sans aucune mise en forme, le format de document le plus simple et le plus portable. Seul l'encodage des caractères peut varier (UTF-8, UTF-16 ou une ancienne page de codes).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Le Markdown est un balisage léger en texte brut : # pour les titres, * pour les listes, ** pour le gras. Il est très utilisé pour les notes, les fichiers README et la documentation, et reste lisible même sans rendu.`],
  [`Web page (HTML)`, `Page web (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `Le HTML est le langage des pages web. Un fichier .html enregistré s'ouvre dans n'importe quel navigateur, mais son apparence dépend du navigateur et des styles et images liés, qui peuvent manquer hors ligne.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `les fichiers LOG et les scripts (PY, PAC, BAT, COMMAND) sont lus comme du texte et jamais exécutés`],
  [`the saved page, with its pictures`, `la page enregistrée, avec ses images`],

  // Data
  [`Data`, `Données`],
  [`data files`, `fichiers de données`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML et XML entre eux, et tableaux depuis et vers CSV et Excel. Contacts vCard depuis et vers CSV, y compris ceux des anciens téléphones. Rien à installer.`],
  [`JSON data`, `Données JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `Le JSON est le format de données du web : objets, listes, texte et nombres en texte brut. Les API, les applications et les fichiers de configuration l'utilisent partout.`],
  [`YAML data`, `Données YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `Le YAML contient le même type de données que le JSON, écrites avec une indentation au lieu d'accolades. Les fichiers de configuration de Docker, Kubernetes, des pipelines de CI et de nombreuses applications sont en YAML.`],
  [`vCard contacts`, `Contacts vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `Le vCard (.vcf) est le fichier standard des contacts. Les téléphones, Outlook, Google Contacts et iCloud exportent les carnets d'adresses en vCard, souvent avec de nombreux contacts dans un seul fichier.`],

  // E-books
  [`E-books & comics`, `Livres numériques et BD`],
  [`e-books and comics`, `livres numériques et bandes dessinées`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook et archives de bandes dessinées (CBZ, CBR, CB7…) en PDF, EPUB, Word et plus, et KEPUB pour les liseuses Kobo. Livres sans DRM uniquement.`],
  [`EPUB e-book`, `Livre numérique EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `L'EPUB est la norme ouverte des livres numériques. Le texte s'adapte à tous les écrans, et la plupart des liseuses et applications de lecture le prennent en charge ; Kindle accepte l'EPUB via Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `Livre numérique Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `Le MOBI est l'ancien format de livre numérique Mobipocket qu'Amazon Kindle a utilisé pendant des années. Il reste courant dans les anciennes collections, mais Amazon est passé à AZW3/KFX et à l'EPUB.`],

  // Video
  [`Video`, `Vidéo`],
  [`video`, `vidéo`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Tous les formats vidéo courants en MP4 (H.264, HEVC ou AV1), WebM, MOV, MKV, AVI, GIF ou APNG, avec une option 720p, l'encodage matériel sur la puce graphique, l'extraction du son en MP3 ou M4A et l'enregistrement de chaque image. Utilise le moteur facultatif FFmpeg.`],
  [`MPEG-4 video`, `Vidéo MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `Le MP4 (MPEG-4 Part 14) est le format vidéo le plus compatible. Il se lit sur les téléphones, les téléviseurs, les navigateurs et tous les sites vidéo, généralement avec une vidéo H.264 ou H.265 et un son AAC.`],
  [`QuickTime movie`, `Vidéo QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `Le MOV est le format vidéo QuickTime d'Apple, utilisé par les iPhone et les Mac. Il contient généralement de la vidéo H.264 ou HEVC, mais certains logiciels de montage, téléviseurs et sites web gèrent mieux le MP4.`],
  [`Matroska video`, `Vidéo Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `Le MKV (Matroska) est un conteneur ouvert et souple qui peut contenir de nombreuses pistes vidéo, audio et de sous-titres. Il est apprécié pour les films et les enregistrements, mais les téléphones, téléviseurs et logiciels de montage ne le lisent pas toujours.`],
  [`WebM video`, `Vidéo WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `Le WebM est un format vidéo ouvert conçu pour les navigateurs (vidéo VP8/VP9 ou AV1 avec son Vorbis ou Opus). Les enregistrements d'écran et les téléchargements sont souvent en WebM, mais beaucoup de logiciels de montage et d'appareils attendent du MP4.`],
  [`AVI video`, `Vidéo AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `L'AVI est le conteneur vidéo de Microsoft des années 1990. Les caméscopes, les anciens appareils photo et les archives contiennent encore des fichiers AVI, souvent lourds et mal pris en charge par les téléphones.`],
  [`one still frame or every frame`, `une image fixe ou chaque image`],

  // Audio
  [`Audio`, `Audio`],
  [`audio`, `audio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Musique, enregistrements et mémos vocaux en MP3, M4A, WAV, FLAC, OGG, Opus, AAC ou en WavPack et TTA sans perte. Les APE, DSD et DTS sont aussi lus. Utilise le moteur facultatif FFmpeg.`],
  [`MP3 audio`, `Audio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `Le MP3 est le format audio compressé classique. Pratiquement tous les lecteurs, autoradios et téléphones le lisent, ce qui en fait le choix le plus sûr pour partager musique, podcasts et enregistrements.`],
  [`MPEG-4 audio`, `Audio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `Le M4A est un fichier audio MPEG-4, généralement en AAC, utilisé par iTunes, les mémos vocaux de l'iPhone et de nombreux enregistreurs. Il sonne bien même à faible taille, mais certains lecteurs et autoradios n'acceptent que le MP3.`],
  [`WAV audio`, `Audio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `Le WAV est un son non compressé (généralement PCM) utilisé pour l'enregistrement et le montage. Il sonne exactement comme la source, mais occupe environ 10 Mo par minute en qualité CD.`],
  [`FLAC lossless audio`, `Audio FLAC sans perte`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `Le FLAC est un son compressé sans perte : il réduit les fichiers à environ la moitié d'un WAV sans perdre la moindre qualité, ce qui en fait le format préféré des bibliothèques musicales et des téléchargements haute résolution.`],

  // Subtitles
  [`Subtitles`, `Sous-titres`],
  [`subtitles`, `sous-titres`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML et MicroDVD entre eux sans aucun moteur, enregistrés en UTF-8 ; les SSA et SCC sont lus. Les fichiers SMI et SRT coréens en CP949 sont lus correctement. Les sous-titres d'une vidéo s'extraient avec FFmpeg.`],
  [`SubRip subtitles`, `Sous-titres SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `Le SRT (SubRip) est le fichier de sous-titres le plus courant : des blocs numérotés avec heure de début et de fin et du texte brut. Presque tous les lecteurs, logiciels de montage et sites vidéo l'acceptent.`],
  [`Advanced SubStation Alpha subtitles`, `Sous-titres Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `L'ASS (Advanced SubStation Alpha) est le format de sous-titres stylés des fansubs d'anime et d'Aegisub, avec polices, couleurs, positions et effets. Beaucoup d'appareils et de sites n'acceptent que le SRT simple.`],
  [`WebVTT subtitles`, `Sous-titres WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `Le WebVTT (.vtt) est le format de sous-titres de la vidéo HTML5. Les lecteurs web, YouTube et les plateformes de cours en ligne l'utilisent.`],
  [`SAMI subtitles (SMI)`, `Sous-titres SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `Le SAMI (.smi) est le format de sous-titres de Microsoft, proche du HTML. C'est toujours le fichier de sous-titres classique en Corée, souvent enregistré dans l'ancien encodage CP949 que les lecteurs récents affichent en caractères illisibles.`],

  // Archives
  [`Archives`, `Archives`],
  [`archives`, `archives`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Recompressez ou extrayez ZIP, 7Z, RAR, TAR, images disque et bien d'autres formats d'archive avec le moteur 7-Zip inclus, ou réunissez n'importe quels fichiers dans un seul ZIP.`],
  [`ZIP archive`, `Archive ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `Le ZIP est le format d'archive universel. Windows, macOS, les téléphones et presque tous les formulaires d'envoi l'ouvrent sans logiciel supplémentaire.`],
  [`7-Zip archive`, `Archive 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `Le 7Z est le format d'archive ouvert de 7-Zip. Sa compression LZMA2 produit généralement des fichiers plus légers que le ZIP, mais tous les systèmes et sites web ne savent pas l'ouvrir.`],
  [`RAR archive`, `Archive RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `Le RAR est le format d'archive propriétaire de WinRAR, courant pour les téléchargements découpés en plusieurs parties. Les versions récentes de Windows 11 ouvrent le RAR sans pouvoir en créer, et beaucoup d'outils n'acceptent que le ZIP.`],
  [`Any files`, `Tous types de fichiers`],

  // CAD
  [`CAD drawings`, `Dessins CAO`],
  [`CAD drawings [in running text]`, `dessins CAO`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG et DXF d'AutoCAD : convertissez-les entre eux ou en PDF, SVG et PNG, sans AutoCAD.`],
  [`AutoCAD drawing`, `Dessin AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `Le DWG est le format de dessin natif d'AutoCAD et le fichier CAO le plus courant en architecture et en ingénierie. Sans AutoCAD ou une visionneuse DWG, il est difficile à ouvrir ou à partager.`],
  [`Drawing Exchange Format`, `Format d'échange de dessins`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `Le DXF (Drawing Exchange Format) est le format d'échange d'Autodesk pour les dessins CAO. Les découpeuses laser, les logiciels de commande numérique et la plupart des programmes de CAO le lisent : c'est le moyen habituel de faire passer des dessins d'un outil à l'autre.`],

  // 3D
  [`3D models`, `Modèles 3D`],
  [`3D models [in running text]`, `modèles 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF et PLY entre eux, et FBX vers chacun d'eux, avec couleurs, textures et matériaux quand le format les conserve, ainsi qu'en image PNG ou JPG ombrée. Rien à installer.`],
  [`glTF binary (GLB)`, `glTF binaire (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `Le GLB est la version en un seul fichier du glTF, le format 3D du web, de la réalité augmentée et des moteurs de jeu. Maillages, matériaux et textures sont réunis dans un seul fichier compact.`],
  [`STL 3D model`, `Modèle 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `Le STL est le fichier classique de l'impression 3D. Il ne stocke que les triangles d'une forme, sans couleurs ni unités, et tous les trancheurs et programmes de CAO le lisent.`],
  [`Wavefront OBJ model`, `Modèle Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `L'OBJ (Wavefront) est un format 3D en texte brut que presque tous les programmes 3D ouvrent. Les matériaux et les textures l'accompagnent dans un fichier .mtl et des images.`],

  // Fonts
  [`Fonts`, `Polices`],
  [`fonts`, `polices`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Polices pour ordinateur et pour le web : TTF, OTF, WOFF, WOFF2 et EOT entre eux.`],
  [`TrueType font`, `Police TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `Le TTF (TrueType) est le format de police le plus courant sous Windows et macOS. Installez-la pour l'utiliser dans n'importe quelle application.`],
  [`OpenType font`, `Police OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `L'OTF (OpenType) est un format de police d'Adobe et de Microsoft. Les polices OpenType à contours PostScript (CFF) sont courantes pour les caractères professionnels et gèrent des fonctions comme les ligatures.`],
  [`Web font (WOFF2)`, `Police web (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `Le WOFF2 est le format de police web compressé pris en charge par tous les navigateurs modernes. Il est en général environ 30 % plus léger que le WOFF : les pages se chargent plus vite.`],

  // Geospatial
  [`Geospatial data`, `Données géospatiales`],
  [`geospatial data`, `données géospatiales`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Cartes et données GPS : GeoJSON, KML, KMZ, GPX et Shapefile entre eux et vers CSV, Excel et JSON, et un CSV avec coordonnées de nouveau en fichier cartographique. Données vectorielles uniquement (points, lignes et surfaces), toujours enregistrées en longitude et latitude. Rien à installer.`],
  [`one row per feature, with its coordinates`, `une ligne par objet, avec ses coordonnées`],
  [`a CSV with longitude and latitude columns or WKT`, `un CSV avec des colonnes longitude et latitude ou WKT`],

  // Camera RAW
  [`Camera RAW photo`, `Photo RAW d'appareil photo`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `Les fichiers RAW d'appareil photo (CR2, CR3, NEF, ARW, DNG, RAF, ORF et autres) contiennent les données brutes du capteur. Ils conservent le maximum de détails pour la retouche, mais sont lourds et nécessitent un logiciel spécialisé pour être affichés.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `Le JPG est le choix sûr quand un site web, une ancienne application Windows ou quelqu'un sans iPhone a besoin de vos photos. Tout un lot de photos HEIC se convertit d'un coup, et chaque JPG est enregistré à côté de son original.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Choisissez le PNG pour continuer à retoucher la photo sans ajouter une passe de compression JPG. Le PNG est sans perte : attendez-vous à des fichiers plusieurs fois plus lourds que le HEIC d'origine.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `Le HEIC stocke une photo dans environ deux fois moins de place qu'un JPG à qualité égale, comme le font les iPhone. L'enregistrement en HEIC nécessite le moteur gratuit FFmpeg (environ 100 Mo, téléchargé une seule fois dans l'application). L'EXIF, le profil de couleur et l'orientation sont conservés.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Les images enregistrées depuis des sites web sont souvent en WebP. La conversion en PNG conserve toute la qualité et la transparence éventuelle : le résultat fonctionne dans tous les éditeurs, présentations et documents.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Choisissez le JPG quand l'image est une photo et que le poids du fichier compte, par exemple pour les formulaires d'envoi qui refusent le WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Les captures d'écran et les photos exportées en PNG peuvent peser plusieurs mégaoctets. Les photos deviennent généralement bien plus légères en JPG ; pour les captures pleines de texte et les logos, le PNG reste souvent le meilleur format.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Convertir un JPG en PNG ne récupère pas les détails perdus par la compression JPG, mais empêche toute perte supplémentaire : chaque retouche et chaque enregistrement ultérieurs restent sans perte. Convertissez avant de retoucher une image ou d'y ajouter de la transparence dans un éditeur.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Les images AVIF des sites web et téléphones récents ne s'ouvrent pas dans beaucoup d'anciens programmes, visionneuses d'images et formulaires d'envoi. Le JPG s'ouvre partout, au prix de fichiers un peu plus lourds.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `Le WebP est idéal pour les sites web : les photos sont bien plus légères qu'en JPG et les graphiques gardent leur transparence. Le préréglage WEBP enregistre en qualité 85, un bon équilibre pour le web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Pages numérisées, tickets de caisse et photos de documents doivent souvent être envoyés en un seul PDF. Déposez les images sur le préréglage Fusionner les PDF pour obtenir un PDF unique, ou sur PDF pour obtenir un PDF par image. Par défaut, chaque page prend la taille de son image.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Un seul ICO couvre tout ce dont Windows a besoin pour les icônes du Bureau, de l'Explorateur et de la barre des tâches, et il sert aussi de favicon pour un site web. Partez d'un PNG carré d'au moins 256×256 px pour un résultat le plus net possible.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Créer une icône d'application Mac sous Windows demande d'habitude des outils supplémentaires ; Filee transforme directement un PNG en fichier ICNS. Utilisez un PNG carré de 1024×1024 px pour que les tailles Retina restent nettes.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Partagez une création Photoshop avec des personnes qui n'ont pas Photoshop : le PNG montre l'image telle qu'elle a été enregistrée, avec les calques visibles fusionnés et la transparence conservée. Le PNG ne stocke pas les calques : gardez le PSD pour la retouche.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee lit les fichiers RAW de Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One et d'autres, et les développe avec les réglages par défaut. C'est le moyen rapide d'obtenir des JPG à partager après une séance photo ; pour une retouche créative, passez d'abord par un logiciel de développement RAW.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Déposez d'un coup les CR2 de toute une carte mémoire : Filee les convertit en parallèle et enregistre chaque JPG à côté de son fichier RAW. Les appareils Canon récents écrivent du CR3, que Filee lit aussi.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `Les fichiers NEF sont trop lourds et trop peu courants pour être envoyés tels quels. En JPG, ils deviennent des photos légères visibles partout ; utilisez JPG 70% ou Taille 50 % pour les messageries. Les fichiers NRW des appareils Nikon Coolpix fonctionnent de la même façon.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Beaucoup d'applications, de présentations et de formulaires d'envoi n'acceptent pas le SVG. Filee fait le rendu du dessin vectoriel en PNG avec transparence ; les fichiers SVGZ compressés fonctionnent aussi.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `Du SVG au PDF, tout reste vectoriel : les traits et le texte restent nets à tous les niveaux de zoom et à l'impression, et le fichier reste léger. Pratique pour envoyer logos et schémas à un imprimeur ou les insérer dans des documents.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `L'EPS ne peut être affiché que par un interpréteur PostScript ; Filee utilise Ghostscript pour cela. Le PDF conserve le dessin vectoriel : il s'ouvre partout et s'imprime toujours net. Les fichiers PostScript (.ps) fonctionnent de la même façon.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Chaque page devient un JPG : un PDF de 10 pages donne 10 images. Pratique pour les messageries, les diapositives et les réseaux sociaux qui acceptent les images mais pas le PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `Le PNG garde le texte et les traits nets, sans les artefacts du JPG : idéal pour les diapositives, les schémas, les partitions et les pages à annoter ou à insérer dans une présentation.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee transforme le PDF en document Word avec de vrais paragraphes au lieu d'images de pages : vous pouvez corriger des fautes ou réutiliser le texte. Les mises en page complexes peuvent demander des retouches, et un PDF numérisé qui ne contient que des images de pages n'a pas de texte à extraire.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee passe tout seul par PDF → Word → EPUB, pour que le texte s'adapte à l'écran d'un téléphone ou d'une liseuse. Cela fonctionne mieux avec des PDF qui contiennent du vrai texte. Les titres deviennent des paragraphes ordinaires, et les pages numérisées n'ont pas de texte à convertir.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee reprend le texte du PDF dans un document Word, l'écrit en HWPX puis l'enregistre en HWP, le tout avec des moteurs intégrés. Cela fonctionne pour les PDF qui contiennent du vrai texte. Les mises en page complexes peuvent demander des retouches, et les pages numérisées n'ont pas de texte à extraire.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee transforme d'abord le PDF en document Word, puis en Markdown, en conservant les paragraphes, les titres et le gras quand il sait les distinguer. Utile pour des notes, des wikis ou pour coller le texte dans d'autres outils. Les pages numérisées n'ont pas de texte à convertir.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Les administrations coréennes demandent souvent des documents au format Hangul. Filee convertit le texte du PDF en fichier HWPX que vous pouvez ouvrir et modifier dans Hancom Hangul, sans Hancom Office pour la conversion ; transformez-le ensuite en HWP si un formulaire exige l'ancien format.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Pratique quand un PDF doit être présenté dans PowerPoint ou ajouté à une présentation existante : chaque page devient une diapositive fidèle au PDF, et le texte de la page attend dans les notes du présentateur. Les diapositives sont des images : pour changer le texte, convertissez plutôt le PDF en DOCX.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Ni Microsoft Word ni LibreOffice ne sont nécessaires : Filee lit lui-même le DOCX et met en page avec les en-têtes, pieds de page, tableaux et images. Déposez plusieurs documents sur le préréglage Fusionner les PDF pour les réunir en un seul PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `Les anciens documents Word 97–2003 issus d'archives, de formulaires officiels ou de systèmes hérités deviennent des PDF qui s'ouvrent partout. Le même moteur convertit aussi les fichiers ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord et Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Enregistrez des e-mails en PDF pour vos archives, vos factures ou vos dossiers juridiques : le PDF affiche l'expéditeur, les destinataires, la date, l'objet et le message, et s'ouvre partout sans logiciel de messagerie.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee fait le rendu des pages HWP avec rhwp, un moteur Hangul open source : ni Hancom Office ni sa fenêtre d'autorisation n'interviennent. Utile pour envoyer des documents coréens à des personnes qui ne peuvent pas ouvrir les HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Transformez un document Hangul en fichier Word que vos collègues à l'étranger pourront modifier. Le texte, les paragraphes et les tableaux sont repris ; les mises en page avec beaucoup d'objets flottants méritent une vérification rapide dans Word.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `Le HWPX, le format Hangul plus récent basé sur XML, se convertit comme le HWP : le moteur intégré rhwp met les pages en forme, entièrement hors ligne. Pratique pour archiver en PDF les formulaires HWPX des institutions publiques.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Certains systèmes et processus récents n'acceptent que le HWPX. Filee convertit le HWP binaire en HWPX avec rhwp, sans Hancom Office, et traite tout un lot d'anciens documents d'un coup.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Les anciennes versions de Hangul et certains portails de dépôt attendent encore du .hwp. Filee reconvertit le HWPX en HWP avec rhwp : inutile d'ouvrir et de réenregistrer chaque fichier dans Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Le rédacteur HWPX de Filee reprend la mise en page Word : format de page et marges, en-têtes et pieds de page avec numéros de page, tableaux à cellules fusionnées, bordures et trames, zones de texte, formes et images. Chaque fichier qu'il écrit est vérifié dans les tests avec trois lecteurs HWPX indépendants.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Pour les administrations et les formulaires qui demandent encore du .hwp. Filee écrit le document Word en HWPX avec son propre rédacteur et le convertit en HWP avec rhwp, tous deux intégrés : Hancom Office n'est pas nécessaire pour la conversion.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Chaque page du document Word devient un JPG (Filee met d'abord le document en page en PDF), pratique pour publier une page en ligne ou envoyer un aperçu rapide. Word n'est pas nécessaire.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Chaque feuille visible devient sa propre section, avec les formats de nombre, les polices, les remplissages, les bordures et les cellules fusionnées tels qu'Excel les affiche. Les feuilles larges sont ajustées à la largeur de la page comme avec « Ajuster toutes les colonnes à une page » d'Excel, et les lignes d'en-tête figées se répètent sur chaque page.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `Un CSV ne contient qu'un seul tableau : Filee écrit donc un CSV par feuille. Les cellules sont exportées en valeurs, prêtes pour les bases de données, les scripts et les formulaires d'import.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Un classeur XLSX peut contenir la mise en forme, les formules et les feuilles supplémentaires que le CSV ne peut pas contenir. Sélectionnez tous vos exports CSV et déposez-les d'un coup pour obtenir un classeur par fichier, sans la fenêtre d'import d'Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Modernisez les anciens classeurs Excel 97–2003 sans Excel ni LibreOffice : la conversion est intégrée. Les fichiers XLSX sont généralement plus légers, ne peuvent pas contenir de macros et s'ouvrent dans tous les tableurs actuels.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Chaque diapositive devient une page PDF à sa taille, avec le texte, les formes, les images, les tableaux et le design du masque. Pratique pour distribuer une présentation ou la déposer là où les fichiers PowerPoint ne sont pas acceptés. Les animations et les notes du présentateur ne figurent pas dans le PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Les anciennes présentations PowerPoint 97–2003 deviennent des PDF que tout le monde peut ouvrir, imprimer ou envoyer. Les présentations Keynote (.key), ODP et WPS (DPS) se convertissent de la même façon.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Chaque diapositive devient un JPG, prêt pour les réseaux sociaux, les miniatures, les messageries ou un logiciel de montage vidéo. Choisissez plutôt le PNG si les diapositives contiennent beaucoup de petit texte.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Titres, listes (y compris les listes de tâches), tableaux, code, citations, liens, images, notes de bas de page et formules mathématiques sont mis en page sur des pages A4, sans Pandoc, LaTeX ni navigateur. Un moyen rapide de partager des notes et des fichiers README avec des personnes qui ne lisent pas le Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Intégré, sans Pandoc. Les titres, listes, tableaux, liens et notes de bas de page sont repris : vous pouvez continuer à modifier le document et à changer sa mise en forme dans Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Le texte brut devient un PDF A4 propre, avec un paragraphe par ligne. Filee reconnaît l'UTF-8 et l'UTF-16 ainsi que les anciens fichiers texte coréens (CP949) : les vieux journaux et notes ne se transforment pas en caractères illisibles.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Enregistrez une page web ou un rapport HTML en PDF qui s'affiche partout de la même façon et peut être archivé ou imprimé. Filee convertit les fichiers .html enregistrés sur votre PC, et plusieurs d'entre eux peuvent être fusionnés en un seul PDF.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `Un PDF garde une mise en page fixe, pratique pour imprimer un livre numérique, le lire sur PC ou l'envoyer sur un appareil sans lecteur EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Passez une ancienne bibliothèque Kindle/Mobipocket en EPUB pour l'ouvrir dans Apple Books, Google Play Livres, Kobo et la plupart des applications de lecture. Ce sens de conversion est intégré : Calibre n'est pas nécessaire.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `C'est l'outil de livres numériques Calibre qui écrit les fichiers MOBI et AZW3. Les Kindle actuels acceptent aussi l'EPUB via Send to Kindle : le MOBI sert surtout aux anciens appareils et applications Kindle.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Enregistrez la bande son d'un cours, d'un concert ou d'une interview en MP3 lisible partout : en voiture, sur un vieux lecteur ou dans un outil de transcription.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `Les vidéos d'iPhone et de Mac sont des fichiers MOV. En MP4, elles se lisent sur les téléphones Android, les téléviseurs connectés, les anciennes applications Windows et les formulaires d'envoi qui refusent le MOV. La vidéo et le son tiennent généralement tels quels dans un MP4 : Filee change seulement de conteneur, sans perte de qualité, HDR conservé, en quelques secondes. Le préréglage MP4 720p réduit les clips 4K pour les partager.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Les enregistrements MKV, par exemple ceux d'OBS, ne s'importent souvent pas dans les logiciels de montage et ne se lisent pas sur les téléviseurs, alors que le MP4 est accepté presque partout. La conversion se fait en local : les longs enregistrements n'ont jamais besoin d'être envoyés en ligne.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Les enregistrements d'écran et les vidéos enregistrées depuis le navigateur sont souvent en WebM, un format que beaucoup de logiciels de montage, d'anciens lecteurs et de messageries gèrent mal. Le MP4 se lit presque partout, et tout un lot de clips se convertit d'un coup.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Transformez un court clip en GIF animé pour les messageries, la documentation ou les rapports de bug. Restez bref : le GIF stocke chaque image en 256 couleurs, et les vidéos longues ou en haute résolution donnent des fichiers très lourds.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Une vidéo déposée sur JPG donne une seule image fixe. Pour choisir une miniature ou parcourir un clip image par image, utilisez le préréglage Extraire les images (JPG) : les images arrivent dans un dossier à côté de la vidéo, chaque image ou une sur N. Une vidéo qui donnerait plus de 100 000 images ou remplirait le disque est refusée avant de commencer.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `Les fichiers AVI des anciens caméscopes et appareils photo sont lourds et utilisent souvent des codecs que les téléphones et téléviseurs ne lisent plus. Un MP4 avec une compression moderne est généralement bien plus léger et se lit partout.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Un enregistrement WAV occupe environ 10 Mo par minute ; en MP3, il n'en faut qu'une fraction et il se lit toujours sur tous les appareils.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Gardez votre bibliothèque FLAC sans perte à la maison et mettez des copies MP3 sur le téléphone, une clé USB pour la voiture ou un ancien lecteur qui ne lit pas le FLAC. Des albums entiers se convertissent d'un coup.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `Les mémos vocaux de l'iPhone, les téléchargements iTunes sans DRM et de nombreux enregistreurs produisent du M4A. Le MP3 est accepté par tous les lecteurs, autoradios et formulaires d'envoi.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Recompressez des archives RAR en ZIP pour les personnes, les formulaires d'envoi et les systèmes qui n'acceptent que le ZIP. WinRAR n'est nécessaire ni pour lire le RAR ni pour écrire le ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `Le 7Z compresse souvent mieux, mais le ZIP s'ouvre sur n'importe quel ordinateur ou téléphone sans logiciel supplémentaire. Convertissez quand vous envoyez une archive à quelqu'un qui n'a pas 7-Zip.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Envoyez des plans à des clients, des équipes de chantier ou des imprimeurs qui n'ont pas AutoCAD : un PDF s'ouvre sur n'importe quel PC ou téléphone. Plusieurs dessins peuvent être fusionnés en un seul PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `Les fichiers DXF issus de programmes de CAO, de travaux de découpe laser ou d'échanges de plans deviennent des PDF que tout le monde peut ouvrir et imprimer. Le SVG et le PNG sont aussi disponibles, par exemple pour des aperçus web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `Le DXF est le format d'échange que lisent les découpeuses laser, les logiciels de commande numérique et la plupart des programmes de CAO. Convertir un DWG en DXF permet d'ouvrir des dessins AutoCAD dans ces outils, et le retour du DXF au DWG fonctionne aussi.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Hébergez vous-même une police sur votre site : le WOFF2 est le format de police web compressé que tous les navigateurs modernes prennent en charge, en général environ 30 % plus léger que le WOFF. Vérifiez que la licence de la police autorise l'intégration web.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Certains anciens programmes, machines de découpe et de broderie et moteurs de jeu n'acceptent que les polices TrueType. Convertissez toute une famille de polices OTF en TTF d'un coup, sans éditeur de polices.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Utilisez Trait en SVG pour les logos, signatures et numérisations : l'encre devient une seule forme noire sur fond transparent. Vectoriser en SVG garde jusqu'à 64 couleurs pour les icônes et illustrations. Les photos ressortent en aplats : la vectorisation convient surtout aux dessins.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Le JPG d'un logo ou d'un croquis numérisé devient un SVG qui reste net à toutes les tailles, prêt pour un traceur de découpe, un site web ou un imprimeur. Le bruit du JPG se transforme en petits points : baissez le réglage Détail du préréglage si le résultat paraît chargé.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Les découpeuses laser, les logiciels de commande numérique et les programmes de CAO lisent le DXF. Filee écrit les contours du SVG en millimètres : une forme de 100 mm de large reste à 100 mm. Les courbes deviennent de fines polylignes. Les remplissages, images et filtres sont omis.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Les e-mails glissés hors d'Outlook sont des fichiers MSG que seul Outlook ouvre. En PDF, ils conservent l'expéditeur, les destinataires, la date, l'objet et le message, et s'ouvrent partout. Outlook n'est pas nécessaire.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `Le YAML est plus facile à lire et à modifier à la main, c'est pourquoi les fichiers de configuration l'utilisent. Les clés gardent leur ordre, et le texte qui serait relu comme un nombre ou comme true/false est mis entre guillemets.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Transformez un fichier de configuration en JSON pour une API, un script ou un outil qui ne lit que le JSON. Les ancres et alias sont résolus, et un fichier à plusieurs documents devient un seul tableau. Les commentaires sont supprimés, puisque le JSON n'en a pas.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Une liste d'enregistrements JSON devient un tableau que vous pouvez ouvrir dans Excel : une ligne par enregistrement, une colonne par clé. Une enveloppe comme {"users": […]} est traversée. Des données qui ne forment pas un tableau s'arrêtent sur un message au lieu de donner un fichier corrompu.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Importez un carnet d'adresses dans Excel ou un outil de publipostage : une ligne par contact, avec nom, organisation, e-mail, téléphone, adresse et anniversaire. Les contacts d'anciens téléphones coréens en CP949 sont lus correctement.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `Les lecteurs web et les plateformes de cours en ligne demandent du WebVTT. Le minutage, les retours à la ligne et l'italique sont conservés, et aucun moteur n'est nécessaire.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Beaucoup de lecteurs, de téléviseurs et de logiciels de montage ne lisent pas le SMI, et les anciens fichiers SMI coréens s'affichent souvent en caractères illisibles. Filee détecte le CP949, choisit la langue qui a le plus de lignes et enregistre un SRT propre en UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Quand un téléviseur, un téléphone ou un site vidéo refuse les sous-titres ASS stylés, le SRT simple fonctionne. Le gras, l'italique, le soulignement et les couleurs sont conservés ; les positions, polices et effets sont supprimés.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Sortez les sous-titres d'un film pour les modifier ou les traduire. La première piste de sous-titres texte est enregistrée en SRT ; les sous-titres en images (DVD, Blu-ray) ne peuvent pas être transformés en texte. Nécessite le moteur gratuit FFmpeg.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Ouvrez un fichier d'impression dans un programme 3D qui préfère l'OBJ. Le STL n'a pas d'unités : Filee le lit en millimètres et écrit l'OBJ en millimètres aussi, avec l'axe Y vers le haut comme la plupart des programmes 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Les trancheurs des imprimantes 3D prennent du STL. Les faces de toute forme sont découpées en triangles, et l'axe Y vers le haut devient Z vers le haut : un modèle debout tient sur le plateau d'impression. Le STL ne garde que la forme : couleurs et textures restent dans l'OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Amenez un modèle du web ou d'un moteur de jeu dans un programme qui lit l'OBJ. Le fichier .mtl et les textures sont écrits à côté du .obj : gardez-les ensemble.`],

  // FAQ
  [`Is Filee really free?`,
    `Filee est-il vraiment gratuit ?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Oui. Filee est gratuit et open source sous licence MIT : pas de publicité, pas de filigrane, pas de compte, pas de période d'essai et aucune limite propre au nombre ou à la taille des fichiers.`],
  [`Does it work offline? Are my files uploaded?`,
    `Fonctionne-t-il hors ligne ? Mes fichiers sont-ils envoyés en ligne ?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Chaque conversion s'effectue sur votre propre PC et les fichiers ne sont jamais envoyés en ligne. Internet ne sert qu'à télécharger un moteur facultatif ou à rechercher les mises à jour : vos documents confidentiels, photos et enregistrements restent sur votre ordinateur.`],
  [`Which file formats does Filee support?`,
    `Quels formats de fichiers Filee prend-il en charge ?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee lit {formatTotal} formats de fichiers dans {categoryCount} catégories : {categoryList}. {builtinTotal} d'entre eux fonctionnent dès l'installation ; les autres utilisent un moteur facultatif gratuit. Le catalogue des formats liste chaque format et ce en quoi il se convertit.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Faut-il Microsoft Office, Hancom Office ou LibreOffice ?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF.`,
    `Non. Les fichiers Word, Excel et PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) et les documents coréens HWP/HWPX sont convertis par des moteurs intégrés à Filee. Filee n'utilise ni Office ni Hancom Office, même s'ils sont installés ; LibreOffice n'est qu'un téléchargement facultatif dans l'application pour les anciens formats comme DOC, PPT, ODT et RTF.`],
  [`What are the optional engines?`,
    `Que sont les moteurs facultatifs ?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `Les gros moteurs ne sont pas inclus dans le programme d'installation. Cochez-les sur sa page des moteurs, ou téléchargez-les dans Filee quand vous en avez besoin : {engineDetails}. Ils sont enregistrés dans le dossier de Filee et peuvent être supprimés à tout moment, et l'application affiche leurs versions, la vitesse de téléchargement et le temps restant. Si FFmpeg, calibre, Pandoc, Ghostscript ou LibreOffice est déjà sur votre PC (dans le PATH, Scoop compris, ou dans Program Files), Filee l'utilise, saute le téléchargement et vous prévient si cette copie est plus ancienne que la version avec laquelle il est testé. Paramètres → Moteurs → Utiliser ma copie permet d'en choisir une précise.`],
  [`Does installing Filee need administrator rights?`,
    `L'installation de Filee nécessite-t-elle des droits d'administrateur ?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Une seule fois, pendant l'installation. Le programme d'installation place Filee dans Program Files pour tous les utilisateurs et, sous Windows 11, ajoute « Convertir avec Filee » en haut du menu de l'Explorateur de fichiers. Filee s'exécute ensuite avec votre compte utilisateur normal. Pour une installation silencieuse, lancez le programme d'installation avec /VERYSILENT /SUPPRESSMSGBOXES. Si vous ne pouvez pas installer de programmes, utilisez le ZIP portable : décompressez-le n'importe où et lancez Filee.exe.`],
  [`Can I convert many files at once?`,
    `Puis-je convertir plusieurs fichiers à la fois ?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Oui. Sélectionnez autant de fichiers que vous voulez et déposez-les en une fois : Filee les convertit en parallèle, un fichier en échec n'arrête jamais les autres, et des préréglages peuvent tout fusionner en un seul PDF ou tout réunir dans un seul ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Puis-je convertir depuis le menu du clic droit de Windows 11 ?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Oui. Faites un clic droit sur des fichiers dans l'Explorateur de fichiers et choisissez « Convertir avec Filee ». Sous Windows 11, vous pouvez aussi placer cette entrée dans le menu principal, sans passer par « Afficher d'autres options » : cliquez une fois sur « Ajouter au menu principal » dans Paramètres → Général et acceptez la demande d'autorisation administrateur. Envoyer vers, un raccourci clavier et la zone de dépôt de la fenêtre principale fonctionnent aussi.`],
  [`Can Filee convert from the command line or automatically?`,
    `Filee peut-il convertir en ligne de commande ou automatiquement ?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Oui. Le programme d'installation peut ajouter la commande filee au PATH : filee convert *.heic --to jpg convertit fichiers, caractères génériques et dossiers avec vos préréglages, produit du JSON pour les scripts et renvoie des codes de sortie. Les dossiers surveillés convertissent automatiquement les fichiers qui arrivent dans un dossier et peuvent mettre les originaux de côté. Configurez-les sur la page Dossiers surveillés de l'application ou avec filee watch dans un terminal.`],
  [`How do I convert a file, for example HEIC to JPG?`,
    `Comment convertir un fichier, par exemple HEIC en JPG ?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Sélectionnez les fichiers dans l'Explorateur de fichiers, maintenez Ctrl (ou la touche choisie) et faites-les glisser. Un menu circulaire de formats s'ouvre sous le curseur : déposez les fichiers sur JPG et les nouveaux fichiers apparaissent à côté des originaux. Des guides pas à pas existent pour les conversions les plus courantes.`],
  [`Why use Filee instead of an online converter?`,
    `Pourquoi utiliser Filee plutôt qu'un convertisseur en ligne ?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `Les convertisseurs en ligne envoient vos fichiers sur le serveur de quelqu'un d'autre, limitent souvent la taille et le nombre de fichiers et dépendent d'une connexion rapide. Filee convertit sur votre PC : vos fichiers privés restent privés, les grosses vidéos et les centaines de fichiers ne posent aucun problème, et tout fonctionne sans Internet, gratuitement et sans publicité.`],
  [`Which operating systems are supported?`,
    `Quels systèmes d'exploitation sont pris en charge ?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 et 11 (64 bits) et Linux (x64 et ARM64, Ubuntu 22.04 ou ultérieur) bénéficient de versions complètes. Sous Linux, le geste de glisser nécessite une session X11 ; sous KDE Plasma avec Wayland, il est expérimental, et sur les autres bureaux Wayland, la zone de dépôt et le menu du clic droit du gestionnaire de fichiers fonctionnent. macOS 13 ou ultérieur (Apple silicon et Intel) est en préversion : l'application n'est pas encore notarisée, macOS vous demande donc de l'autoriser une fois dans Confidentialité et sécurité. Choisissez votre système dans la section de téléchargement.`],
]);
